const listing = $('Set Listing Details').first().json;
const raw = $input.first().json.output_text || '{}';
let brief;
try { brief = JSON.parse(raw); } catch { brief = { title: listing.address, generation_prompt: raw, caption: raw }; }
return [{ json: { type: 'video_ad', template_slug: 'viral-video-ads', prompt: brief.generation_prompt, aspect_ratio: '9:16', duration: 8, quality_tier: 'high', reference_image_urls: listing.listing_image_urls || [], brand_kit_id: $vars.VIDEOTOK_BRAND_KIT_ID, idempotency_key: `real-estate-listing-${$execution.id}`, caption: brief.caption, compliance_notes: brief.compliance_notes } }];
